(3470955, 484403, 39144, '<td valign="top">Excellent work on the setup and editing of this photo. It is awesome!</td>', 'Excellent work on the setup and editing of this photo. It is awesome!', '2007-03-19 00:12:35.000000', NULL, 1),
(3470962, 485188, 19982, '<td valign="top">Beautifully done.  I''ve heard some people say to clone out any extra catch lights if there is more than one per eye, but I don''t mind this at all, I think it really adds to the "life" in her eyes.</td>', 'Beautifully done.  I''ve heard some people say to clone out any extra catch lights if there is more than one per eye, but I don''t mind this at all, I think it really adds to the "life" in her eyes.', '2007-03-19 00:13:34.000000', NULL, 1),
