INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3472669, 484176, 56254, '<td valign="top">wish the focus was more on the farmer ... he gets lost behind that big ol John Deere ... I''d like to see this in B/W after the challenge is over</td>', 'wish the focus was more on the farmer ... he gets lost behind that big ol John Deere ... I''d like to see this in B/W after the challenge is over', '2007-03-19 13:06:35.000000', NULL, 1),
(3472671, 485834, 74059, '<td valign="top">This has awesome color and the light catching in her eye is great, but I wish she had a different expression on her face.</td>', 'This has awesome color and the light catching in her eye is great, but I wish she had a different expression on her face.', '2007-03-19 13:06:43.000000', NULL, 1),
(3472672, 485494, 39144, '<td valign="top">It may be silly, but it is a pretty decent photo. I hope you took som landscape shots after the portrait!</td>', 'It may be silly, but it is a pretty decent photo. I hope you took som landscape shots after the portrait!', '2007-03-19 13:07:02.000000', NULL, 1),
(3472673, 485534, 70000, '<td valign="top">It would be nice to see alot more sharpness in her face, it looks a bit overprocessed in contrast with the naturalness of her hair</td>', 'It would be nice to see alot more sharpness in her face, it looks a bit overprocessed in contrast with the naturalness of her hair', '2007-03-19 13:07:07.000000', NULL, 1),
(3472674, 485695, 74059, '<td valign="top">Very nice lighting.  It''s super dark but it really works.</td>', 'Very nice lighting.  It''s super dark but it really works.', '2007-03-19 13:07:19.000000', NULL, 1),
(3472675, 485312, 56254, '<td valign="top">colors work well together ... but his skin takes on a lot of the red from the door ...</td>', 'colors work well together ... but his skin takes on a lot of the red from the door ...', '2007-03-19 13:07:21.000000', NULL, 1),
(3472676, 484989, 39144, '<td valign="top">Very captivating eyes on this image.</td>', 'Very captivating eyes on this image.', '2007-03-19 13:07:32.000000', NULL, 1),
(3472678, 485491, 56254, '<td valign="top">lighting is sort of dull ...</td>', 'lighting is sort of dull ...', '2007-03-19 13:08:14.000000', NULL, 1),
(3472680, 482988, 55199, '<td valign="top">Nice smiles. :)  I have 3 children, so I know what its like.  The little girls ruffle on the bottom of her outfit is a little distracting, as is the blue and brown stripes against the green floral print of their outfits. Otherwise, nice job.</td>', 'Nice smiles. :)  I have 3 children, so I know what its like.  The little girls ruffle on the bottom of her outfit is a little distracting, as is the blue and brown stripes against the green floral print of their outfits. Otherwise, nice job.', '2007-03-19 13:08:29.000000', NULL, 1),
(3472681, 484487, 39144, '<td valign="top">How can someone not appreciate a photo like this. Nice job. The background vignetting is not very smooth however. Was that an effect of the capture, or the processing? Either way, something I would recommend to look in to next time.</td>', 'How can someone not appreciate a photo like this. Nice job. The background vignetting is not very smooth however. Was that an effect of the capture, or the processing? Either way, something I would recommend to look in to next time.', '2007-03-19 13:08:48.000000', NULL, 1),
(3472682, 483824, 3102, '<td valign="top">A very cute and natural pose, but the white balance is really off on this one, I''m afraid.  It''s way too cyan.</td>', 'A very cute and natural pose, but the white balance is really off on this one, I''m afraid.  It''s way too cyan.', '2007-03-19 13:09:10.000000', NULL, 1),
(3472684, 484797, 56254, '<td valign="top">his skin has a blue tint to it</td>', 'his skin has a blue tint to it', '2007-03-19 13:09:33.000000', NULL, 1),
(3472685, 485081, 45115, '<td valign="top">looks like he was pasted on the background. great pose anyway!</td>', 'looks like he was pasted on the background. great pose anyway!', '2007-03-19 13:09:55.000000', NULL, 1),
(3472686, 485724, 39144, '<td valign="top">Nice job on isolating this child from the background. The portrait itself appears a little flat, like a curves adjustment could be helpful to really make this photo pop.</td>', 'Nice job on isolating this child from the background. The portrait itself appears a little flat, like a curves adjustment could be helpful to really make this photo pop.', '2007-03-19 13:10:00.000000', NULL, 1),
(3472687, 485619, 70000, '<td valign="top">I think you didnt have the take out what she was leaning on, now it looks like she is just leaning in air and it looks sort of unnatural and the edge of her arm is uneven, i really love her face and the colors in her clothing though and its nicely lit</td>', 'I think you didnt have the take out what she was leaning on, now it looks like she is just leaning in air and it looks sort of unnatural and the edge of her arm is uneven, i really love her face and the colors in her clothing though and its nicely lit', '2007-03-19 13:10:16.000000', NULL, 1),
(3472690, 485274, 55199, '<td valign="top">A little work on the eyes would raise this up a notch.  You can use the ellipse selection tool to select just the irises and pupils, then play with color adjustments and add sharpness, to let the windows to your soul shine.  :)</td>', 'A little work on the eyes would raise this up a notch.  You can use the ellipse selection tool to select just the irises and pupils, then play with color adjustments and add sharpness, to let the windows to your soul shine.  :)', '2007-03-19 13:13:04.000000', NULL, 1),
(3472691, 485242, 3102, '<td valign="top">Very, very busy, and I really wouldn''t consider it a portrait.</td>', 'Very, very busy, and I really wouldn''t consider it a portrait.', '2007-03-19 13:13:24.000000', NULL, 1),
(3472692, 485375, 45115, '<td valign="top">great!!</td>', 'great!!', '2007-03-19 13:14:12.000000', NULL, 1),
