(3484201, 485670, 66384, '<td valign="top">Beautiful image. Not my idea of a portrait. 8</td>', 'Beautiful image. Not my idea of a portrait. 8', '2007-03-23 19:36:02.000000', NULL, 1),
(3484206, 485704, 5728, '<td valign="top">This is such a cool idea, but I really would have liked to see the colors and saturation punched up more, it would have done so much more for the image!</td>', 'This is such a cool idea, but I really would have liked to see the colors and saturation punched up more, it would have done so much more for the image!', '2007-03-23 19:38:21.000000', NULL, 1),
